import{_ as a}from"./chunks/PM_work.B_kLj-6q.js";import{_ as e,o as i,c as r,a2 as l}from"./chunks/framework.CHeM0PsO.js";const o="/img/steps.png",s="/img/PM_process.png",p="/img/work_output.png",n="/img/design_flow.png",_="/img/design_strategy.png",P=JSON.parse('{"title":"商业化产品“七步设计法” 1","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/steps.md","filePath":"knowledge/steps.md","lastUpdated":null}'),c={name:"knowledge/steps.md"};function m(d,t,h,g,f,u){return i(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="商业化产品-七步设计法-1" tabindex="-1">商业化产品“七步设计法” <a href="http://www.woshipm.com/pd/3784247.html" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#商业化产品-七步设计法-1" aria-label="Permalink to &quot;商业化产品“七步设计法” [1]&quot;">​</a></h1><p>方法论试图提炼出从0到1设计商业化产品的通用思路，重点介绍宏观设计逻辑，即具备普适性的全链路商业化产品设计流程，而不倾向于介绍某款单品类产品的设计细节。但也会在各个流程环节会特别说明适用的产品，比如适合to C产品还是to B产品，或者适合广告产品、会员产品还是其他商业化产品。</p><h2 id="如何设计一款专业的、具备竞争力的商业化产品呢" tabindex="-1">如何设计一款专业的、具备竞争力的商业化产品呢？ <a class="header-anchor" href="#如何设计一款专业的、具备竞争力的商业化产品呢" aria-label="Permalink to &quot;如何设计一款专业的、具备竞争力的商业化产品呢？&quot;">​</a></h2><p>你们可能会从不同的视角给出不同的答案，这可能是岗位差异造成的。然而，当我们从公司的视角考虑商业化产品设计时，就必须具备全局思维，即面向商业化全链路来设计可闭环变现的产品。</p><p>在商业流通市场中，无论商业化产品属于哪种形态或者哪个种类，产品所遵循的商业化底层逻辑是相通的，即无论你的变现模式是卖流量、卖软件、卖服务，还是其他的变现模式，最终你卖的都是“商品”，都需要遵循商业化规律和一些普适的商业操作标准。</p><p><img src="'+o+'" alt="打造一份优秀作品的步骤"></p><h2 id="七步设计法" tabindex="-1">“七步设计法” <a class="header-anchor" href="#七步设计法" aria-label="Permalink to &quot;“七步设计法”&quot;">​</a></h2><p><img src="'+s+'" alt="一个完整的产品案例3"></p><ol><li>输出BRD、资源评估报告等。</li><li>输出产品设计规划、解决方案设计规划等。</li><li>输出PRD（产品需求文档）、产品交付清单等。</li><li>输出产品报价单、SKU目录、财务模型等。</li><li>输出售卖渠道策略、售卖政策、销售协议等。</li><li>输出各类商业化产品包装资料、商业化产品官网等。</li><li>输出产品发布管理文档、各类产品培训资料等。</li></ol><p><img src="'+p+'" alt="工作输出4"><img src="'+n+'" alt="设计流程与方法5"><img src="'+_+'" alt="设计策略:双钻石模型6"></p><h2 id="工作" tabindex="-1">工作 <a class="header-anchor" href="#工作" aria-label="Permalink to &quot;工作&quot;">​</a></h2><ol><li>计划:使用计划系列卡来定义产品的关键要素并调整团队成员在一个战线节奏和目标上。</li><li>调研:使用调研系列卡来收集有关市场和用户的数据并分析他们的可用性。</li><li>理解:使用理解系列卡来合成相关数据并发现有价值的见解。</li><li>思考:使用思考系列卡来提升你的洞察力并创造有价值的新想法。</li><li>评估:使用评估系列卡来检测你的构思并针对现实情况收集反馈意见。<a href="https://www.zhihu.com/search?type=content&amp;q=AI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86" target="_blank" rel="noreferrer">3</a></li></ol><p><img src="'+a+'" alt="PM work"></p>',13)])])}const b=e(c,[["render",m]]);export{P as __pageData,b as default};
